tags.expression:
//  Availability = Run Time / Planned Production Time
// Capped at 1: a counter reset or an interval that has only just started can
// otherwise report run seconds ahead of elapsed seconds for a few samples.
min(if({[.]SecondsElapsed} = 0, 1,
{[.]RunSeconds} /{[.]SecondsElapsed}), 1)

//Performance = Production Count / Target Production Count
// Capped at 1: running above the target rate, or a partially-elapsed interval
// straight after a rollover, would otherwise show Performance over 100%.
min(if({[.]TargetProductionCount}=0,1,{[.]ProductionCount}/{[.]TargetProductionCount}), 1)

//seconds between interval starting time and now
//zero if the start time is now, or this instance is disabled
if({[.]StartTime} = None || {[.]Enabled}  = 0 ,0,
min(secondsBetween({[.]StartTime},now(250)),{[.]Duration})
)

//  Utilization = Planned Production Time / All Time
min(if({[.]SecondsElapsed} = 0, 1,
({[.]SecondsElapsed}  - {[.]IdleSeconds}) /{[.]SecondsElapsed}), 1)

// Shift start time. A shift that does not cross midnight started today.
// One that does (StartTime > StopTime) started today while the clock is still
// past its start, and yesterday once we are past midnight. The stock expression
// always subtracted a day, dating the shift a day early for its whole pre-midnight
// half -- which left ShiftOee elapsed/target inconsistent and Performance > 100%.
if({[.]CurrentShift}=1 && {[.]1/StartTime} < {[.]1/StopTime},setTime(now(0), floor({[.]1/StartTime} /100) , {[.]1/StartTime} %100,0)
,if({[.]CurrentShift}=2 && {[.]2/StartTime} < {[.]2/StopTime},setTime(now(0), floor({[.]2/StartTime} /100) , {[.]2/StartTime} %100,0)
,if({[.]CurrentShift}=3 && {[.]3/StartTime} < {[.]3/StopTime},setTime(now(0), floor({[.]3/StartTime} /100) , {[.]3/StartTime} %100,0)
,if({[.]CurrentShift}=1 && {[.]1/StartTime} > {[.]1/StopTime},setTime(if({[.]CurrentHourMinute} >= {[.]1/StartTime}, now(0), addDays(now(0),-1)), floor({[.]1/StartTime} /100) , {[.]1/StartTime} %100,0)
,if({[.]CurrentShift}=2 && {[.]2/StartTime} > {[.]2/StopTime},setTime(if({[.]CurrentHourMinute} >= {[.]2/StartTime}, now(0), addDays(now(0),-1)), floor({[.]2/StartTime} /100) , {[.]2/StartTime} %100,0)
,if({[.]CurrentShift}=3 && {[.]3/StartTime} > {[.]3/StopTime},setTime(if({[.]CurrentHourMinute} >= {[.]3/StartTime}, now(0), addDays(now(0),-1)), floor({[.]3/StartTime} /100) , {[.]3/StartTime} %100,0)
,setTime(now(0),0,0,0)))))))
